        return parts

    # Actually, let's use a simpler approach: build the output string directly
    # by replacing placeholders with raw HTML, then using a custom serialization

    # Get all text content including tails
    result_parts = []

    # Process text content
    text = elem.text
    if text:
        # Replace stash placeholders with raw HTML
        def _html_sub(m):
            try:
